mapper.select:
SELECT id, user_id, title, note, status, due_date, created_at, updated_at, completed_at FROM todos WHERE user_id = #{userId}
AND status = #{status}
ORDER BY CASE WHEN status = 'open' THEN 0 ELSE 1 END, due_date IS NULL, due_date ASC, updated_at DESC

mapper.insert:
INSERT INTO todos (
  id, user_id, title, note, status, due_date, created_at, updated_at, completed_at
) VALUES (
  #{id}, #{userId}, #{title}, #{note}, #{status}, #{dueDate},
  #{createdAt}, #{updatedAt}, #{completedAt}
)

mapper.update:
UPDATE todos
SET title = #{title},
    note = #{note},
    status = #{status},
    due_date = #{dueDate},
    updated_at = #{updatedAt},
    completed_at = #{completedAt}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM todos
WHERE id = #{id}
  AND user_id = #{userId}
